

# This file was *autogenerated* from the file controlExp.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_200 = Integer(200); _sage_const_1000 = Integer(1000); _sage_const_1p2 = RealNumber('1.2'); _sage_const_20 = Integer(20); _sage_const_0 = Integer(0); _sage_const_100 = Integer(100); _sage_const_150 = Integer(150); _sage_const_250 = Integer(250); _sage_const_300 = Integer(300)# controlExp.sage
#
# Kontrolni eksperiment uz geometricExp.sage.
#
# Za svaki generisan RGG(N, r) graf izvlaci se njegov degree sequence,
# i pravi se PAROVANI "kontrolni" graf koji ima IDENTICAN taj niz
# stepena, ali je inace nasumican (configuration model / degree-
# -preserving randomizacija - koristi se networkx.random_degree_
# sequence_graph, koji radi Havel-Hakimi realizaciju pa je nasumicno
# "meša" double-edge-swap operacijama, i garantuje PROST graf sa
# tacno tim nizom stepena).
#
# Svrha: RGG ima jaku geometrijsku korelaciju (visok clustering
# coefficient, jer blizina dve tacke trecoj implicira blizinu njih
# dve, po nejednakosti trougla). Kontrolni graf ima ISTI niz stepena
# kao odgovarajuci RGG, ali bez te geometrijske korelacije - ivice su
# nasumicno rasporedjene uz jedino ogranicenje da stepeni ostanu isti.
#
# Ako kontrolni graf da rezultate BLIZE Erdos-Renyi ponasanju
# (cyclic_fraction ~ 0.79, mean_2_rank ~ 1) nego RGG, to potvrdjuje da
# je bas GEOMETRIJSKA KORELACIJA (clustering), a ne sama raspodela
# stepena, uzrok toga sto RGG kriticne grupe retko budu ciklicne.
#
# Struktura eksperimenata je ista kao u geometricExp.sage (2-rank i
# ciklicnost), samo sto se sada za svaki N prate DVE paralelne serije
# statistika: RGG i control (uparen sa istim degree sequence).
#


import csv
import math
import random
import networkx as nx


# Pomocne funkcije - zajednicke za oba eksperimenta


def reduced_laplacian(G):
    L = G.laplacian_matrix()
    n = L.nrows()
    return L.delete_rows([n - _sage_const_1 ]).delete_columns([n - _sage_const_1 ])


def p_rank_value(Lr, p):
    """p-rank(G) = (n-1) - rank(L mod p), racunato nad GF(p).
    n se izvlaci direktno iz dimenzije reduced Laplasijana."""
    n = Lr.nrows() + _sage_const_1 
    Lp = Lr.change_ring(GF(p))
    r = Lp.rank()
    return (n - _sage_const_1 ) - r


def two_rank_of_graph(G):
    Lr = reduced_laplacian(G)
    return p_rank_value(Lr, _sage_const_2 )


def is_cyclic_critical_group(G):
    """True ako je p-rank(G) <= 1 za SVE proste p <= n = G.order()."""
    n = G.order()
    Lr = reduced_laplacian(G)
    for p in prime_range(n + _sage_const_1 ):
        if p_rank_value(Lr, p) > _sage_const_1 :
            return False
    return True


# Generisanje RGG grafa (isto kao u geometricExp.sage)

def connectivity_threshold(N):
    """r_c(N) = sqrt( log(N) / (pi * N) )."""
    return math.sqrt(math.log(N) / (math.pi * N))


def random_geometric_graph(N, r):
    pts = [(random.random(), random.random()) for _ in range(N)]

    G = Graph()
    G.add_vertices(range(N))

    r2 = r * r
    for i in range(N):
        xi, yi = pts[i]
        for j in range(i + _sage_const_1 , N):
            xj, yj = pts[j]
            dx = xi - xj
            dy = yi - yj
            if dx * dx + dy * dy < r2:
                G.add_edge(i, j)

    G.set_pos({i: pts[i] for i in range(N)})
    return G


def random_connected_rgg(N, r, max_attempts=_sage_const_200 ):
    """Ponavlja generisanje RGG(N, r) dok graf ne ispadne povezan.
    Ako ne uspe posle max_attempts pokusaja, baca gresku (c je
    verovatno premalo za dato N - vidi geometricExp.sage)."""
    for _ in range(max_attempts):
        G = random_geometric_graph(N, r)
        if G.is_connected():
            return G

    raise RuntimeError(
        f"N={N}, r={r:.4f}: nije dobijen povezan RGG posle "
        f"{max_attempts} pokusaja. Povecaj radius_multiplier."
    )


# Generisanje kontrolnog grafa (isti degree sequence, nasumican inace)

def control_graph_from_degree_sequence(deg_seq, max_attempts=_sage_const_200 , swap_tries=_sage_const_200 ):
    """Vraca PROST graf (Sage Graph) sa TACNO istim nizom stepena kao
    deg_seq, generisan kao slucajna realizacija (configuration model +
    double-edge-swap randomizacija, via networkx.random_degree_
    sequence_graph). Ponavlja dok graf ne ispadne povezan."""
    for _ in range(max_attempts):
        try:
            H_nx = nx.random_degree_sequence_graph(deg_seq, tries=swap_tries)
        except nx.NetworkXUnfeasible:
            raise RuntimeError(
                "Dati degree sequence nije realizabilan kao prost graf."
            )
        if nx.is_connected(H_nx):
            H = Graph(H_nx)
            H.relabel()  # cvorovi 0..n-1, redosled po svojoj konvenciji
            return H

    raise RuntimeError(
        f"Nije dobijen povezan kontrolni graf sa zadatim degree "
        f"sequence posle {max_attempts} pokusaja."
    )


def paired_rgg_and_control(N, r):
    """Generise jedan RGG i njemu uparen kontrolni graf sa istim
    degree sequence. Vraca (G_rgg, G_control)."""
    G_rgg = random_connected_rgg(N, r)
    deg_seq = G_rgg.degree()  # lista stepena svih cvorova
    G_control = control_graph_from_degree_sequence(deg_seq)
    return G_rgg, G_control


# EKSPERIMENT 1: 2-RANK (RGG naspram control)

def run_two_rank_experiment(N_values, num_graphs=_sage_const_1000 , radius_multiplier=_sage_const_1p2 , verbose=True):
    results = {}

    for N in N_values:

        r = radius_multiplier * connectivity_threshold(N)

        two_ranks_rgg = []
        two_ranks_control = []

        for i in range(num_graphs):
            G_rgg, G_control = paired_rgg_and_control(N, r)

            two_ranks_rgg.append(two_rank_of_graph(G_rgg))
            two_ranks_control.append(two_rank_of_graph(G_control))

            if verbose and (i + _sage_const_1 ) % _sage_const_20  == _sage_const_0 :
                print(f"  [2-rank] N={N}: obradjeno {i + _sage_const_1 }/{num_graphs} parova")

        mean_rgg = sum(two_ranks_rgg) / len(two_ranks_rgg)
        mean_control = sum(two_ranks_control) / len(two_ranks_control)

        results[N] = {
            "r": r,
            "mean_two_rank_rgg": mean_rgg,
            "mean_two_rank_control": mean_control,
        }

        print(f"[2-rank] N={N:>4}  r={r:.4f}  |  "
              f"mean_2_rank RGG = {float(mean_rgg):.3f}   "
              f"mean_2_rank control = {float(mean_control):.3f}")

    return results


def save_two_rank_csv(results, filename="controlExp_two_rank.csv"):
    with open(filename, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["N", "r", "mean_two_rank_rgg", "mean_two_rank_control"])
        for N, data in results.items():
            writer.writerow([
                N, float(data["r"]),
                float(data["mean_two_rank_rgg"]),
                float(data["mean_two_rank_control"]),
            ])
    print(f"\n[2-rank] Rezultati sacuvani u: {filename}")


# EKSPERIMENT 2: CIKLICNOST (RGG naspram control)

def run_cyclicity_experiment(N_values, num_graphs=_sage_const_1000 , radius_multiplier=_sage_const_1p2 , verbose=True):
    results = {}

    for N in N_values:

        r = radius_multiplier * connectivity_threshold(N)

        cyclic_count_rgg = _sage_const_0 
        cyclic_count_control = _sage_const_0 

        for i in range(num_graphs):
            G_rgg, G_control = paired_rgg_and_control(N, r)

            if is_cyclic_critical_group(G_rgg):
                cyclic_count_rgg += _sage_const_1 
            if is_cyclic_critical_group(G_control):
                cyclic_count_control += _sage_const_1 

            if verbose and (i + _sage_const_1 ) % _sage_const_20  == _sage_const_0 :
                print(f"  [cyclic] N={N}: obradjeno {i + _sage_const_1 }/{num_graphs} parova")

        frac_rgg = cyclic_count_rgg / num_graphs
        frac_control = cyclic_count_control / num_graphs

        results[N] = {
            "r": r,
            "cyclic_fraction_rgg": frac_rgg,
            "cyclic_fraction_control": frac_control,
        }

        print(f"[cyclic] N={N:>4}  r={r:.4f}  |  "
              f"cyclic_fraction RGG = {float(frac_rgg):.3f}   "
              f"cyclic_fraction control = {float(frac_control):.3f}")

    return results


def save_cyclicity_csv(results, filename="controlExp_cyclicity.csv"):
    with open(filename, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["N", "r", "cyclic_fraction_rgg", "cyclic_fraction_control"])
        for N, data in results.items():
            writer.writerow([
                N, float(data["r"]),
                float(data["cyclic_fraction_rgg"]),
                float(data["cyclic_fraction_control"]),
            ])
    print(f"\n[cyclic] Rezultati sacuvani u: {filename}")


# Pokretanje

if __name__ == "__main__":
    # Iste N vrednosti kao u geometricExp.sage / erdosExp.sage
    N_values = [_sage_const_100 , _sage_const_150 , _sage_const_200 , _sage_const_250 , _sage_const_300 ]
    num_graphs = _sage_const_1000 
    radius_multiplier = _sage_const_1p2   # r = radius_multiplier * r_c(N), blizu praga povezanosti

    print("=== EKSPERIMENT 1: 2-RANK (RGG naspram control) ===\n")
    two_rank_results = run_two_rank_experiment(
        N_values, num_graphs=num_graphs, radius_multiplier=radius_multiplier
    )
    save_two_rank_csv(two_rank_results)

    print("\n\n=== EKSPERIMENT 2: CIKLICNOST (RGG naspram control) ===\n")
    cyclicity_results = run_cyclicity_experiment(
        N_values, num_graphs=num_graphs, radius_multiplier=radius_multiplier
    )
    save_cyclicity_csv(cyclicity_results)

